const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Simplified Lake Erie polygon
  var lakeErie = ee.Geometry.Polygon([
    [[-83.0, 41.5], [-82.0, 41.5], [-82.0, 42.5], 
     [-83.0, 42.5], [-83.0, 41.5]]
  ]);

  // Date ranges (single day each)
  var date1 = '2014-01-09';
  var date2 = '2014-01-14';

  // Function to get ice area for a specific date
  function getIceArea(date) {
    var collection = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(lakeErie);

    var size = collection.size().getInfo();
    print(date + ' Images:', size);

    if (size === 0) {
      return {area: null, validPixels: 0, hasData: false};
    }

    var image = collection.first();

    // Get NDSI band (Normalized Difference Snow Index)
    var ndsi = image.select('NDSI').multiply(0.0001); // Scale factor

    // Quality mask - use QA band bits 0-1 (0=best, 1=good)
    var qa = image.select('QA');
    var qualityMask = qa.bitwiseAnd(3).lt(2); // Keep best and good quality

    // Apply quality mask and threshold for ice (NDSI > 0.4)
    var iceMask = ndsi.updateMask(qualityMask).gt(0.4);

    // Count valid pixels
    var pixelCount = iceMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: lakeErie,
      scale: 500, // MODIS resolution
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    // Calculate area in square km
    var area = iceMask.multiply(ee.Image.pixelArea()).divide(1000000); // m² to km²
    var areaValue = area.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeErie,
      scale: 500,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    return {
      area: areaValue,
      validPixels: pixelCount || 0,
      hasData: true
    };
  }

  // 2. Data Acquisition & Check
  var result1 = getIceArea(date1);
  var result2 = getIceArea(date2);

  // Check for empty collections
  if (!result1.hasData || !result2.hasData) {
    print("One or both dates have no data.");
    print("<answer>C1</answer>");
    return;
  }

  // Check for no valid pixels
  if (result1.validPixels === 0 || result2.validPixels === 0) {
    print("No valid ice pixels detected.");
    print("Jan 9 valid pixels:", result1.validPixels);
    print("Jan 14 valid pixels:", result2.validPixels);
    print("<answer>C2</answer>");
    return;
  }

  // 3. Calculation & Validation
  print("Jan 9 Ice Area (km²):", result1.area);
  print("Jan 14 Ice Area (km²):", result2.area);
  print("Jan 9 Valid Pixels:", result1.validPixels);
  print("Jan 14 Valid Pixels:", result2.validPixels);

  // Check for calculation failure
  if (result1.area === null || result2.area === null || 
      isNaN(result1.area) || isNaN(result2.area)) {
    print("Calculation failed - null or NaN result.");
    print("<answer>C3</answer>");
    return;
  }

  // Check for unrealistic values (NDSI range is -1 to 1, area should be reasonable)
  if (result1.area < 0 || result2.area < 0 || 
      result1.area > 100000 || result2.area > 100000) { // Lake Erie area ~25,700 km²
    print("Unrealistic ice area detected.");
    print("<answer>C3</answer>");
    return;
  }

  // 4. Final Answer
  var decrease = result2.area < result1.area;

  if (decrease) {
    print("Ice extent decreased from Jan 9 to Jan 14.");
    print("<answer>A</answer>");
  } else {
    print("Ice extent did not decrease from Jan 9 to Jan 14.");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
